import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"偏好设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/preferences.md","filePath":"zh/guides/preferences.md","lastUpdated":1790952322000}'),a={name:"zh/guides/preferences.md"};function n(s,t,h,i,l,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="偏好设置" tabindex="-1">偏好设置 <a class="header-anchor" href="#偏好设置" aria-label="Permalink to &quot;偏好设置&quot;">​</a></h1><p>Memoh v0.13 提供客户端级别的用户偏好设置。它们会改变当前设备配置档里的界面观感和快捷键行为，不会改变 Bot 的人格、模型、工具、记忆或访问规则。</p><p>打开 <strong>Settings</strong>，在 <strong>Appearance</strong> 调整视觉偏好，在 <strong>Keyboard</strong> 调整快捷键。</p><hr><h2 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h2><p><strong>Appearance</strong> 页面分为界面、字体与字号、代码高亮、图表几个部分。修改会立即生效。</p><h3 id="界面" tabindex="-1">界面 <a class="header-anchor" href="#界面" aria-label="Permalink to &quot;界面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设置</th><th>作用</th></tr></thead><tbody><tr><td><strong>Language</strong></td><td>设置界面语言。v0.13 包含 English、简体中文和日本語。如果还没有手动选择，Memoh 会根据浏览器语言识别英文、中文或日文，并在无法识别时回退到英文。</td></tr><tr><td><strong>Theme</strong></td><td>选择 Light、Dark 或 System。System 会跟随操作系统或浏览器的颜色模式。</td></tr><tr><td><strong>Color Scheme</strong></td><td>更换品牌元素、状态颜色和界面控件使用的强调色方案。可选 Memoh、Ocean、Forest、Rose、Amber。</td></tr></tbody></table><p>这里的语言只影响 Memoh 界面。Bot 回复时使用什么语言，仍在 Bot 设置里配置。</p><h3 id="字体与字号" tabindex="-1">字体与字号 <a class="header-anchor" href="#字体与字号" aria-label="Permalink to &quot;字体与字号&quot;">​</a></h3><p>如果界面太小、太大，或你想换代码字体，可以在这里调整。</p><table tabindex="0"><thead><tr><th>设置</th><th>影响范围</th><th>范围 / 默认值</th></tr></thead><tbody><tr><td><strong>UI Font Size</strong></td><td>常规界面文字和控件</td><td><code>12</code>-<code>20</code> px，默认 <code>16</code></td></tr><tr><td><strong>Code Font Size</strong></td><td>代码编辑器、Markdown 代码块和终端文字</td><td><code>11</code>-<code>20</code> px，默认 <code>13</code></td></tr><tr><td><strong>UI Font Family</strong></td><td>主界面字体</td><td>默认 <code>system-ui, sans-serif</code></td></tr><tr><td><strong>Code Font Family</strong></td><td>代码、编辑器和终端字体栈</td><td>默认 <code>ui-monospace, monospace</code></td></tr></tbody></table><p>字体字段接受普通 CSS 风格的字体栈，例如 <code>Inter, system-ui, sans-serif</code> 或 <code>&quot;JetBrains Mono&quot;, ui-monospace, monospace</code>。对应字体需要已经存在于你的设备或浏览器环境中。清空字段，或填入默认值，可以回到 Memoh 默认字体栈。</p><h3 id="代码高亮" tabindex="-1">代码高亮 <a class="header-anchor" href="#代码高亮" aria-label="Permalink to &quot;代码高亮&quot;">​</a></h3><p>Memoh 使用 Shiki 主题渲染代码高亮。你可以分别选择浅色模式和深色模式下的主题：</p><table tabindex="0"><thead><tr><th>设置</th><th>影响范围</th></tr></thead><tbody><tr><td><strong>Light theme</strong></td><td>界面处于浅色模式时的代码块和编辑器</td></tr><tr><td><strong>Dark theme</strong></td><td>界面处于深色模式时的代码块和编辑器</td></tr></tbody></table><p>主题选择器会搜索内置 Shiki 主题列表，并显示实时预览，方便你在离开页面前对比浅色和深色选择。</p><h3 id="图表" tabindex="-1">图表 <a class="header-anchor" href="#图表" aria-label="Permalink to &quot;图表&quot;">​</a></h3><p>聊天和 Markdown 预览中渲染的 Mermaid 图表会使用 <strong>Mermaid Theme</strong> 偏好。</p><table tabindex="0"><thead><tr><th>主题</th><th>行为</th></tr></thead><tbody><tr><td><strong>Auto</strong></td><td>跟随当前界面模式。</td></tr><tr><td><strong>Default</strong></td><td>使用 Mermaid 默认浅色主题。</td></tr><tr><td><strong>Dark</strong></td><td>使用 Mermaid 深色主题。</td></tr><tr><td><strong>Forest</strong></td><td>使用 Mermaid forest 主题。</td></tr><tr><td><strong>Neutral</strong></td><td>使用 Mermaid neutral 主题。</td></tr></tbody></table><p>如果某个图表已经写了自己的 Mermaid 初始化指令，它可能会保留文档作者指定的主题；这适合需要固定图表风格的文档。</p><hr><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><p><strong>Keyboard</strong> 页面会按作用域列出可编辑快捷键。点击某一行的 <strong>Edit</strong>，按下新的组合键，然后保存。</p><h3 id="默认快捷键" tabindex="-1">默认快捷键 <a class="header-anchor" href="#默认快捷键" aria-label="Permalink to &quot;默认快捷键&quot;">​</a></h3><p>macOS 上显示为 <code>Cmd</code>，Windows 和 Linux 上显示为 <code>Ctrl</code>。</p><table tabindex="0"><thead><tr><th>动作</th><th>默认快捷键</th><th>作用域</th></tr></thead><tbody><tr><td>关闭当前工作区标签页</td><td>桌面应用中为 <code>Cmd/Ctrl + W</code>。在普通浏览器里，浏览器会保留原生关闭标签页行为。</td><td>全局</td></tr><tr><td>保存当前文件</td><td><code>Cmd/Ctrl + S</code></td><td>全局</td></tr><tr><td>切换侧边栏</td><td><code>Cmd/Ctrl + B</code></td><td>全局</td></tr><tr><td>打开设置</td><td><code>Cmd/Ctrl + K</code></td><td>全局</td></tr><tr><td>关闭媒体灯箱</td><td><code>Esc</code></td><td>媒体灯箱</td></tr><tr><td>上一张媒体</td><td><code>Left Arrow</code></td><td>媒体灯箱</td></tr><tr><td>下一张媒体</td><td><code>Right Arrow</code></td><td>媒体灯箱</td></tr></tbody></table><p>全局快捷键在应用内普遍生效。媒体灯箱快捷键只在媒体预览覆盖层打开时生效。</p><h3 id="修改规则" tabindex="-1">修改规则 <a class="header-anchor" href="#修改规则" aria-label="Permalink to &quot;修改规则&quot;">​</a></h3><p>保存快捷键前，Memoh 会先检查组合键：</p><ul><li><code>Cmd/Ctrl + W</code>、<code>Cmd/Ctrl + Q</code>、<code>Cmd/Ctrl + T</code>、<code>Cmd/Ctrl + N</code> 保留给浏览器或操作系统。</li><li>全局快捷键必须包含 <code>Cmd/Ctrl</code> 或 <code>Alt</code>，避免普通输入时误触应用命令。</li><li>同一作用域内，两条快捷键不能使用同一个组合键。</li><li>不同作用域可以共用组合键，但 Memoh 会提示警告，因为只有当前活跃的作用域会处理它。</li></ul><p>用某一行的重置按钮可以恢复单个快捷键。用 <strong>Reset all</strong> 可以清空所有自定义快捷键。</p><hr><h2 id="实用说明" tabindex="-1">实用说明 <a class="header-anchor" href="#实用说明" aria-label="Permalink to &quot;实用说明&quot;">​</a></h2><ul><li>外观和快捷键是个人 UI 偏好，不会影响其他用户或 Bot。</li><li>偏好保存在当前设备/浏览器配置档里，换浏览器或换机器后可能需要重新设置。</li><li>如果试字体或快捷键后界面不合预期，可以回到同一页面重置对应字段或快捷键。</li></ul>',35)])])}const g=d(a,[["render",n]]);export{p as __pageData,g as default};
